import bisect
import re
from dataclasses import dataclass
from datetime import date, datetime
from fractions import Fraction

from .errors import ValidationError


class CurrencyError(ValidationError):
    pass


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


CURRENCIES = {
    c.code: c
    for c in (
        Currency("USD", 2, "US Dollar", "$"),
        Currency("EUR", 2, "Euro", "€"),
        Currency("GBP", 2, "British Pound", "£"),
        Currency("JPY", 0, "Japanese Yen", "¥"),
        Currency("CHF", 2, "Swiss Franc", "CHF"),
        Currency("CAD", 2, "Canadian Dollar", "CA$"),
        Currency("AUD", 2, "Australian Dollar", "A$"),
        Currency("KWD", 3, "Kuwaiti Dinar", "KD"),
        Currency("SEK", 2, "Swedish Krona", "kr"),
        Currency("INR", 2, "Indian Rupee", "₹"),
        Currency("NZD", 2, "New Zealand Dollar", "NZ$"),
        Currency("NOK", 2, "Norwegian Krone", "kr"),
        Currency("KRW", 0, "South Korean Won", "₩"),
        Currency("BHD", 3, "Bahraini Dinar", "BD"),
        Currency("CNY", 2, "Chinese Yuan", "CN¥"),
        Currency("MXN", 2, "Mexican Peso", "MX$"),
    )
}


def currency(code):
    if not isinstance(code, str) or code not in CURRENCIES:
        raise CurrencyError("unknown currency '%s'" % (code,))
    return CURRENCIES[code]


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def _check_date(on):
    if not isinstance(on, date) or isinstance(on, datetime):
        raise CurrencyError("invalid date '%s': expected a date" % (on,))


class RateTable:
    def __init__(self):
        self._data = {}  # (src, dst) -> sorted list of (date, Fraction)

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        if not isinstance(rate_text, str) or not _RATE_RE.fullmatch(rate_text):
            raise CurrencyError("invalid rate '%s'" % (rate_text,))
        value = Fraction(rate_text)
        if value <= 0:
            raise CurrencyError("invalid rate '%s': must be positive" % rate_text)
        _check_date(on)
        rows = self._data.setdefault((src, dst), [])
        i = bisect.bisect_left(rows, (on,))
        if i < len(rows) and rows[i][0] == on:
            rows[i] = (on, value)
        else:
            rows.insert(i, (on, value))

    def _latest(self, src, dst, on):
        rows = self._data.get((src, dst))
        if not rows:
            return None
        i = bisect.bisect_right(rows, (on, Fraction(10) ** 100)) - 1
        return rows[i][1] if i >= 0 else None

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._latest(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._latest(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, on.isoformat()))

    def convert(self, money, dst, on):
        from .money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("cannot convert '%s': not an amount of money" % (money,))
        e_dst = currency(dst).exponent
        _check_date(on)
        if money.currency == dst:
            return money
        r = self.rate(money.currency, dst, on)
        e_src = CURRENCIES[money.currency].exponent
        num = money.minor * r.numerator * 10 ** e_dst
        den = r.denominator * 10 ** e_src
        return Money(round_div(num, den), dst)

    def entries(self):
        out = []
        for (src, dst), rows in self._data.items():
            for on, value in rows:
                out.append((src, dst, on, value))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        rows = self._data.get((src, dst))
        if rows:
            i = bisect.bisect_left(rows, (on,))
            if i < len(rows) and rows[i][0] == on:
                del rows[i]
                if not rows:
                    del self._data[(src, dst)]
                return
        raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, on.isoformat()))
"""Strict dates, month arithmetic and periods."""
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

from .errors import ParseError


class DateError(ParseError):
    pass


def is_date(x):
    return isinstance(x, date) and not isinstance(x, datetime)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': expected text" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= month <= 12 or not 1 <= year <= 9999:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    if not _is_int(n):
        raise DateError("months must be an integer, got '%s'" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    y, m = divmod(total, 12)
    m += 1
    if not 1 <= y <= 9999:
        raise DateError("date out of range: %s plus %d months" % (format_date(d), n))
    return date(y, m, min(d.day, last_day(y, m)))


@dataclass(frozen=True)
class Period:
    start: date
    end: date

    def __post_init__(self):
        if not is_date(self.start) or not is_date(self.end):
            raise DateError("period needs two dates, got '%s' and '%s'" % (self.start, self.end))
        if self.end < self.start:
            raise DateError("empty period: %s is before %s" % (format_date(self.end), format_date(self.start)))

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: '%s'" % (d,))
        return self.start <= d <= self.end

    @property
    def days(self):
        return (self.end - self.start).days + 1

    def _kind(self):
        s, e = self.start, self.end
        if s.day != 1:
            return None
        if s.month == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if e.year == s.year and e.month == s.month and e.day == last_day(e.year, e.month):
            return "month"
        if (
            s.month in (1, 4, 7, 10)
            and e.year == s.year
            and e.month == s.month + 2
            and e.day == last_day(e.year, e.month)
        ):
            return "quarter"
        return None

    @property
    def label(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self.start), format_date(self.end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        s = self.start
        try:
            if kind == "year":
                return _year(s.year + 1)
            if kind == "month":
                return _month_after(s)
            if kind == "quarter":
                nxt = add_months(s, 3)
                return _span(nxt, add_months(nxt, 3) - timedelta(days=1))
            ns = self.end + timedelta(days=1)
            return Period(ns, ns + timedelta(days=self.days - 1))
        except OverflowError:
            raise DateError("period after %s is out of range" % self.label) from None

    @staticmethod
    def parse(text):
        return _parse_period(text)


def _span(a, b):
    return Period(a, b)


def _year(y):
    if not 1 <= y <= 9999:
        raise DateError("year %d is out of range" % y)
    return Period(date(y, 1, 1), date(y, 12, 31))


def _month_after(s):
    nxt = add_months(s, 1)
    return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))


def _month_of(y, m):
    return Period(date(y, m, 1), date(y, m, last_day(y, m)))


_YEAR_RE = re.compile(r"([0-9]{4})")
_MONTH_RE = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER_RE = re.compile(r"([0-9]{4})-Q([1-4])")


def _parse_period(text):
    if not isinstance(text, str):
        raise DateError("invalid period '%s': expected text" % (text,))
    try:
        m = _YEAR_RE.fullmatch(text)
        if m:
            return _year(int(m.group(1)))
        m = _MONTH_RE.fullmatch(text)
        if m:
            return _month_of(int(m.group(1)), int(m.group(2)))
        m = _QUARTER_RE.fullmatch(text)
        if m:
            y, q = int(m.group(1)), int(m.group(2))
            first = _month_of(y, 3 * q - 2)
            return Period(first.start, _month_of(y, 3 * q).end)
        parts = text.split("..")
        if len(parts) == 2:
            return Period(parse_date(parts[0]), parse_date(parts[1]))
    except (DateError, ValueError):
        pass
    raise DateError("invalid period '%s'" % text)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        start = d - timedelta(days=d.weekday())
        return Period(start, start + timedelta(days=6))
    if step == "month":
        return _month_of(d.year, d.month)
    if step == "quarter":
        q = (d.month - 1) // 3
        return Period(date(d.year, 3 * q + 1, 1), _month_of(d.year, 3 * q + 3).end)
    return _year(d.year)


def periods(start, end, step):
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got '%s' and '%s'" % (start, end))
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    p = _containing(start, step)
    out = [p]
    while p.end < end:
        p = _containing(p.end + timedelta(days=1), step)
        out.append(p)
    return out

